package com.payflow.transaction; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/transactions") public class TransactionController { final TransactionRepo repo; public TransactionController(TransactionRepo r){repo=r;} @GetMapping("/account/{id}") public List<TransactionRecord> byAccount(@PathVariable Long id){return repo.findTop50BySenderAccountIdOrderByCreatedAtDesc(id);} }
